// Synthetic but model-based ONT raw signal for the hero.
//
// The hidden word, its DNA and the expected current of every event live in
// src/data/squiggle.json, generated by `node scripts/squiggle-model.mjs WORD`
// from ONT's R10.4.1 e8.2 400 bps 9-mer level table (standardised units).
// Noise: SD 0.128 of the level spread (ratio of sd_mean to level_mean spread
// in ONT's legacy R9.4 450 bps 6-mer pA model; R10.4.1 tables give no noise).
// Dwell: gamma (shape 3), mean 12.5 samples per base (5 kHz / 400 bps),
// floored at 0.6 of the mean so every label stays readable.
import model from '../data/squiggle.json';

function mulberry32(seed: number) {
  return () => {
    seed |= 0; seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// [base, expected level]; the first event is unlabelled flank
const EVENTS: [string, number][] = model.events.map((e) => [e.base, e.level]);
const NOISE_SD = 0.128;
const SAMPLES_PER_BASE = 12.5;

export interface Event { base: string; x0: number; x1: number; y0: number; }
export interface Squiggle { d: string; events: Event[]; }

export function squiggle(width = 1200, height = 140, seed = 11): Squiggle {
  const rand = mulberry32(seed);
  const gauss = () => {
    const u = 1 - rand(), v = rand();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  // Marsaglia-Tsang gamma sampler (shape >= 1), scale 1
  const gamma = (k: number) => {
    const d = k - 1 / 3, c = 1 / Math.sqrt(9 * d);
    for (;;) {
      let x: number, v: number;
      do { x = gauss(); v = 1 + c * x; } while (v <= 0);
      v = v * v * v;
      const u = rand();
      if (Math.log(u) < 0.5 * x * x + d - d * v + d * Math.log(v)) return d * v;
    }
  };
  const lv = EVENTS.map((e) => e[1]);
  const lo = Math.min(...lv) - 0.45, hi = Math.max(...lv) + 0.45;
  const toY = (lvl: number) => height - ((lvl - lo) / (hi - lo)) * height;

  // samples per event; the leading flank is shown partially
  const counts = EVENTS.map((_, i) => {
    const n = Math.max(0.6, gamma(3) / 3) * SAMPLES_PER_BASE;
    return Math.max(4, Math.round(i === 0 ? n * 0.6 : n));
  });
  const total = counts.reduce((a, b) => a + b, 0);
  const dx = width / (total - 1);

  const pts: string[] = [];
  const events: Event[] = [];
  let k = 0;
  let lastY = 0;
  EVENTS.forEach(([base, level], i) => {
    const x0 = k * dx - (i ? dx / 2 : 0);
    let firstY = 0;
    for (let j = 0; j < counts[i]; j++, k++) {
      const y = +toY(level + gauss() * NOISE_SD).toFixed(1);
      if (j === 0) firstY = y;
      pts.push(`${(k * dx).toFixed(1)},${y}`);
    }
    // the boundary sits halfway between two samples, so the drawn signal
    // crosses it exactly at the mean of their y values
    const cross = (lastY + firstY) / 2;
    lastY = +pts[pts.length - 1].split(',')[1];
    if (i === 0) return;
    events.push({
      base,
      x0: +x0.toFixed(1),
      x1: +Math.min(width, k * dx - dx / 2).toFixed(1),
      y0: +cross.toFixed(2),
    });
  });
  events[events.length - 1].x1 = width;
  return { d: 'M' + pts.join('L'), events };
}

// Random (unlabelled) trace, used on the 404 page.
export function squigglePath(width = 1200, height = 140, seed = 7): string {
  const rand = mulberry32(seed);
  const gauss = () => {
    const u = 1 - rand(), v = rand();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const step = 2;
  const mid = height / 2;
  const pts: string[] = [];
  let x = 0;
  let level = 0;
  const openPore = 90;
  while (x <= width) {
    let dwell: number;
    if (x < openPore) {
      level = -height * 0.36;
      dwell = openPore;
    } else {
      level = (rand() - 0.5) * height * 0.62;
      dwell = 8 + Math.floor(rand() * 26);
    }
    for (let i = 0; i < dwell && x <= width; i += step, x += step) {
      const y = mid + level + gauss() * height * 0.025;
      pts.push(`${x},${y.toFixed(1)}`);
    }
  }
  return 'M' + pts.join('L');
}
